// Mod 2: ANSWER. Hold shell commands that delete folders or overwrite work.
import { why } from './rules.js'

async function guard($, e, next) {
  const reason = why(e.command)
  // No next(e): the command never runs, and Claude reads this sentence instead
  if (reason) return { deny: 'Held by the guard mod: this command ' + reason + '. Ask the user first.' }
  return next(e)
}

export function register(on) {
  // If the guard itself breaks, hold the command instead of letting it through
  on('tool.call', { tool: 'Bash' }, guard).catch(async ($, e, next) => {
    if (next.called) return next(e)
    return { deny: 'The guard mod failed, so this command was not run: ' + next.error.kind }
  })
}

