// The guard's rules: a test for the command, and the reason Claude is given.
export const RULES = [
  [(c) => /\brm\b/.test(c) && flag(c, 'r') && flag(c, 'f'), 'deletes a whole folder with no way back'],
  [(c) => /\bgit\s+push\b/.test(c) && /--force\b|\s-f\b/.test(c), 'overwrites the history on the server'],
  [(c) => /\bgit\s+reset\s+--hard\b/.test(c), 'throws away work that was never saved'],
  [(c) => /\bgit\s+clean\b/.test(c) && flag(c, 'f'), 'deletes files git does not know'],
]

// true when a one-letter flag is somewhere in the command: -rf, -fr, -r -f, -Rf
function flag(command, letter) {
  return command.split(/\s+/).some((w) => /^-[a-zA-Z]+$/.test(w) && w.toLowerCase().includes(letter))
}

// The reason a command is risky, or null when it is fine
export function why(command) {
  for (const [risky, reason] of RULES) if (risky(command)) return reason
  return null
}

